  // A hand: a glove (or a bare hand) with the knuckles of the fingers round the grip.
  const hand=(hx,hy,dir=0)=>{oval(hx,hy,2.9,2.4,dir);shade(GLV,hx-.6,hy-.6,3,1,1);for(const o of [-1,0,1])seg(hx+Math.cos(dir)*1.6-Math.sin(dir)*o*1,hy+Math.sin(dir)*1.6+Math.cos(dir)*o*1,hx+Math.cos(dir)*2.6-Math.sin(dir)*o*1,hy+Math.sin(dir)*2.6+Math.cos(dir)*o*1,dim(GLV,.5),.45,.8);};
  // The guns from above: wood and polymer with their grain, blued steel with a line of light down the barrel.
